// recipe: virtual-key
// args: key=s down=n
// serves: cross-player-eat-skips-native-steps (the give batch needed the inventory key, which is the game's own binding)
// returns: ok, key, down, staged, held, installed, error, detail
//
// The acceptance channel's virtual KEYBOARD, one key per call: installs the Input patches and then stages (down=1) or releases (down=0) ONE key by the
// game's own enum name — `Tab` for the inventory panel, the `/` key for the console. The patches answer `Input.GetKey`/`GetKeyDown`/`GetKeyUp` for that
// key only (every other key stays the real keyboard's), and the press is stamped for the NEXT frame because an eval can run after this frame's Update.
((System.Func<string>)(() => { var keyName = {{s:key}}; var down = {{n:down}} != 0; var findType = new System.Func<string, System.Type>((simpleName) => { var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < assemblies.Length; i++) { System.Type[] types; try { types = assemblies[i].GetTypes(); } catch { continue; } for (var t = 0; t < types.Length; t++) { if (types[t].Name == simpleName) { return types[t]; } } } return null; }); var vi = findType("VirtualInput"); if (vi == null) { return "{\"ok\":false,\"error\":\"no-VirtualInput\"}"; } System.Type keyType = null; var asms = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < asms.Length && keyType == null; i++) { keyType = asms[i].GetType("UnityEngine.KeyCode"); } if (keyType == null) { return "{\"ok\":false,\"error\":\"no-KeyCode\"}"; } object key; try { key = System.Enum.Parse(keyType, keyName); } catch { return "{\"ok\":false,\"error\":\"bad-key\",\"detail\":\"" + keyName + "\"}"; } const System.Reflection.BindingFlags F = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; var install = vi.GetMethod("Install", F); var installedReport = (string)install.Invoke(null, new object[] { false }); if (down) { vi.GetMethod("PressKey", F).Invoke(null, new object[] { key }); } else { vi.GetMethod("ReleaseKey", F).Invoke(null, new object[] { key }); } var staged = (int)vi.GetProperty("StagedKeyCount", F).GetValue(null, null); var installed = (bool)vi.GetProperty("Installed", F).GetValue(null, null); return "{\"ok\":true,\"key\":\"" + keyName + "\",\"down\":" + (down ? "true" : "false") + ",\"staged\":" + staged + ",\"installed\":" + (installed ? "true" : "false") + ",\"report\":\"" + installedReport.Replace("\\", "\\\\").Replace("\"", "'").Replace("\n", " | ") + "\"}"; }))()
